STATE_NAME_BY_CODE: dict[str, str] = {code: name for code, name in US_STATES}


def get_cities(state_code: str) -> list[str]:
    """Return the city list for a state code (uppercase 2 letters).

    Empty list if the code isn't recognised.
    """
    return list(CITIES_BY_STATE.get((state_code or '').upper(), []))


def get_state_name(state_code: str) -> str:
    """Return the full state name for a 2-letter code, or '' if unknown."""
    return STATE_NAME_BY_CODE.get((state_code or '').upper(), '')
